import { useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext.jsx';

/**
 * Invite-only administrator/staff registration.
 * Links generated by the admin console look like:
 *   /admin/register?invite=<one-time-token>&email=<invited-email>
 */
export default function AdminRegister() {
  const { user, acceptAdminInvite } = useAuth();
  const navigate = useNavigate();
  const [params] = useSearchParams();

  const inviteToken = params.get('invite') || '';
  const invitedEmail = params.get('email') || '';

  const [form, setForm] = useState({
    name: '',
    email: invitedEmail,
    password: '',
    confirm: '',
  });
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  const update = (name, value) => setForm((prev) => ({ ...prev, [name]: value }));

  if (user) {
    return (
      <main className="admin-auth-page">
        <div className="admin-auth-card">
          <h1>Already signed in</h1>
          <p>
            You are signed in as <strong>{user.name}</strong> ({user.role}). Open the admin
            console instead.
          </p>
          <div className="auth-links">
            <Link to={user.role === 'customer' ? '/' : '/admin'} className="btn btn-primary">
              {user.role === 'customer' ? 'Back to storefront' : 'Open admin console'}
            </Link>
          </div>
        </div>
      </main>
    );
  }

  if (!inviteToken) {
    return (
      <main className="admin-auth-page">
        <div className="admin-auth-card">
          <div className="admin-auth-brand">
            <span aria-hidden="true">💊</span>
            <strong>MediTrack</strong>
            <small>Admin console</small>
          </div>
          <h1>Invite required</h1>
          <p>
            Administrator and staff accounts are created by invitation. Ask an administrator
            for an invite link, then open it to finish registration.
          </p>
          <Link to="/admin/login" className="btn btn-secondary">
            Back to back-office sign-in
          </Link>
        </div>
      </main>
    );
  }

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');

    if (form.password !== form.confirm) {
      setError('The passwords do not match.');
      return;
    }

    setSubmitting(true);
    try {
      await acceptAdminInvite({
        token: inviteToken,
        name: form.name,
        email: form.email,
        password: form.password,
      });
      navigate('/admin', { replace: true });
    } catch (err) {
      setError(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <main className="admin-auth-page">
      <div className="admin-auth-card">
        <div className="admin-auth-brand">
          <span aria-hidden="true">💊</span>
          <strong>MediTrack</strong>
          <small>Admin console</small>
        </div>

        <h1>Accept your invite</h1>
        <p>This invite is single-use and expires automatically.</p>

        <form className="medicine-form" onSubmit={handleSubmit}>
          <div className="field">
            <label htmlFor="invite-name">Full name</label>
            <input
              id="invite-name"
              type="text"
              value={form.name}
              onChange={(e) => update('name', e.target.value)}
              autoComplete="name"
              required
            />
          </div>

          <div className="field">
            <label htmlFor="invite-email">Email</label>
            <input
              id="invite-email"
              type="email"
              value={form.email}
              readOnly={Boolean(invitedEmail)}
              onChange={(e) => update('email', e.target.value)}
              autoComplete="username"
              required
            />
            {invitedEmail && (
              <p className="file-hint">This invite is issued for {invitedEmail}.</p>
            )}
          </div>

          <div className="field">
            <label htmlFor="invite-password">Password</label>
            <input
              id="invite-password"
              type="password"
              value={form.password}
              onChange={(e) => update('password', e.target.value)}
              autoComplete="new-password"
              minLength={8}
              required
            />
          </div>

          <div className="field">
            <label htmlFor="invite-confirm">Confirm password</label>
            <input
              id="invite-confirm"
              type="password"
              value={form.confirm}
              onChange={(e) => update('confirm', e.target.value)}
              autoComplete="new-password"
              minLength={8}
              required
            />
          </div>

          <button type="submit" className="btn btn-primary btn-block" disabled={submitting}>
            {submitting ? 'Creating account…' : 'Create account'}
          </button>

          {error && (
            <p className="error" role="alert">
              {error}
            </p>
          )}
        </form>

        <p className="auth-hint">
          Never share this link: whoever opens it first can create the account.{' '}
          <Link to="/admin/login">Back to sign-in</Link>
        </p>
      </div>
    </main>
  );
}
